import { RequestHandler } from '@builder.io/qwik-city';
import { getDb } from '../db';

export const onRequest: RequestHandler = async (event) => {
  const sessionCookie = event.cookie.get('session');
  if (sessionCookie) {
    const sessionId = sessionCookie.value;
    try {
      const db = await getDb();
      const sessionUser = await db.get<{ id: number; username: string; role: string }>(
        `SELECT u.id, u.username, u.role FROM sessions s 
         JOIN users u ON s.user_id = u.id 
         WHERE s.id = ?`,
        sessionId
      );
      if (sessionUser) {
        event.sharedMap.set('user', sessionUser);
      }
    } catch (err) {
      console.error('Error resolving session:', err);
    }
  }
};

import { RequestHandler } from '@builder.io/qwik-city';
import { getDb } from '../../../db';
import { randomUUID } from 'crypto';

export const onPost: RequestHandler = async (event) => {
  try {
    const body = await event.request.json();
    const { username, password } = body || {};

    if (!username || !password) {
      event.status(401);
      event.json(401, { error: 'Invalid credentials' });
      return;
    }

    const db = await getDb();
    const user = await db.get<{ id: number; username: string; password?: string; role: string }>(
      'SELECT id, username, password, role FROM users WHERE username = ?',
      username
    );

    if (!user || user.password !== password) {
      event.status(401);
      event.json(401, { error: 'Invalid credentials' });
      return;
    }

    const sessionId = randomUUID();
    await db.run('INSERT INTO sessions (id, user_id) VALUES (?, ?)', sessionId, user.id);

    event.cookie.set('session', sessionId, {
      path: '/',
      httpOnly: true,
      sameSite: 'lax',
    });

    event.json(200, {
      username: user.username,
      role: user.role,
    });
  } catch (err) {
    event.status(401);
    event.json(401, { error: 'Invalid credentials' });
  }
};

import { RequestHandler } from '@builder.io/qwik-city';
import { getDb } from '../../../db';

export const onPost: RequestHandler = async (event) => {
  const sessionCookie = event.cookie.get('session');
  if (sessionCookie) {
    const sessionId = sessionCookie.value;
    try {
      const db = await getDb();
      await db.run('DELETE FROM sessions WHERE id = ?', sessionId);
    } catch (err) {
      console.error('Error invalidating session:', err);
    }
    event.cookie.delete('session', { path: '/' });
  }
  event.json(200, { message: 'Logged out successfully' });
};

